/* Temporary functional round-trip test for prepare_jadwal Save/Load.
 * Loads the concatenated page JS (generated by _validate_templates.py) into a
 * vm sandbox with a stubbed DOM, then exercises save -> JSON -> load.
 */
const fs = require("fs");
const vm = require("vm");
const path = require("path");

const appJs = fs.readFileSync(path.join(".tmp_validate", "app.js"), "utf8");

const failures = [];
function check(name, cond, extra) {
  if (cond) {
    console.log("  ok  - " + name);
  } else {
    console.log("  FAIL- " + name + (extra !== undefined ? " :: " + JSON.stringify(extra) : ""));
    failures.push(name);
  }
}

// ---------- DOM stubs ----------
function makeEl(overrides) {
  const el = {
    value: "",
    textContent: "",
    innerHTML: "",
    disabled: false,
    checked: false,
    files: [],
    dataset: {},
    style: {},
    href: "",
    download: "",
    classList: { add() {}, remove() {}, contains() { return false; } },
    addEventListener() {},
    appendChild() {},
    removeChild() {},
    remove() {},
    append() {},
    focus() {},
    click() {},
    setAttribute() {},
    getAttribute() { return null; },
    querySelector() { return makeEl(); },
    querySelectorAll() { return []; },
    parentElement: null,
  };
  return Object.assign(el, overrides || {});
}

const store = {};
function byId(id) {
  if (!store[id]) store[id] = makeEl();
  return store[id];
}

const radios = [
  makeEl({ value: "existing", checked: true }),
  makeEl({ value: "balanced", checked: false }),
];

let lastQuery = null;
const documentStub = {
  getElementById: byId,
  querySelector(sel) { lastQuery = sel; return makeEl(); },
  querySelectorAll(sel) {
    if (sel.indexOf("distribution_method") !== -1) return radios;
    return [];
  },
  createElement() { return makeEl(); },
  body: makeEl(),
  addEventListener() {},
  open() {}, write() {}, close() {},
};

let lastDownload = { json: null, filename: null, href: null };
class FakeBlob {
  constructor(parts, opts) { this.text = (parts || []).join(""); this.type = opts && opts.type; }
}
const URLStub = {
  createObjectURL(blob) { lastDownload.json = JSON.parse(blob.text); return "blob:fake-url"; },
  revokeObjectURL() {},
};

// capture created <a> (download trigger)
const origCreateElement = documentStub.createElement;
documentStub.createElement = function (tag) {
  const el = makeEl();
  if (tag === "a") {
    el.click = function () { lastDownload.filename = el.download; lastDownload.href = el.href; };
  }
  return el;
};

let alerts = [];
let fetchCalls = [];
class FakeFileReader {
  readAsText(file) { this.result = file.__text; if (this.onload) this.onload({ target: this }); }
}

const sandbox = {
  document: documentStub,
  window: {},
  console: { log() {}, error() {}, warn() {} },
  bootstrap: { Tab: { getOrCreateInstance() { return { show() {} }; } } },
  Blob: FakeBlob,
  URL: URLStub,
  FormData: class { append() {} },
  alert(msg) { alerts.push(msg); },
  fetch() { fetchCalls.push(Array.prototype.slice.call(arguments)); return Promise.resolve({ json: () => Promise.resolve({}) }); },
  FileReader: FakeFileReader,
  setTimeout: setTimeout,
  JSON: JSON,
  Object: Object,
  Array: Array,
  Math: Math,
  Date: Date,
  parseInt: parseInt,
  parseFloat: parseFloat,
  isNaN: isNaN,
};
sandbox.globalThis = sandbox;

vm.createContext(sandbox);
vm.runInContext(appJs, sandbox, { filename: "app.js" });

console.log("== Save: interval ==");
byId("start_time").value = "09:30";
byId("interval_hour").value = "12";
radios[0].checked = false; radios[1].checked = true; // balanced
sandbox.saveIntervalSettings();
const intervalJson = lastDownload.json;
check("interval type", intervalJson.type === "upload_schedule_settings", intervalJson.type);
check("interval version", intervalJson.version === 1, intervalJson.version);
check("interval method", intervalJson.method === "interval", intervalJson.method);
check("interval distribution", intervalJson.distribution_method === "balanced", intervalJson.distribution_method);
check("interval config.start_time", intervalJson.config.start_time === "09:30", intervalJson.config);
check("interval config.interval_hour numeric", intervalJson.config.interval_hour === 12, intervalJson.config);
check("interval has no upload_directory", !("upload_directory" in intervalJson) && !("upload_directory" in intervalJson.config));
check("interval has no start_date", !("start_date" in intervalJson) && !("start_date" in intervalJson.config));
check("interval filename", lastDownload.filename === "upload_schedule_settings_interval.json", lastDownload.filename);

console.log("== Save: fixed ==");
byId("upload_time").value = "20:00";
sandbox.addUploadTime();
byId("upload_time").value = "08:00";
sandbox.addUploadTime();
sandbox.saveFixedSettings();
const fixedJson = lastDownload.json;
check("fixed method", fixedJson.method === "fixed", fixedJson.method);
check("fixed upload_times sorted", JSON.stringify(fixedJson.config.upload_times) === JSON.stringify(["08:00", "20:00"]), fixedJson.config);
check("fixed no upload_directory/start_date", !("upload_directory" in fixedJson) && !("start_date" in fixedJson));

console.log("== Save: weekly ==");
byId("monday_time").value = "07:00";
sandbox.addWeeklyTime("monday");
byId("monday_time").value = "21:00";
sandbox.addWeeklyTime("monday");
