check("weekly Monday badge", JSON.stringify(weeklyJson.config.weekly_schedule.Monday) === JSON.stringify(["07:00", "21:00"]), weeklyJson.config.weekly_schedule.Monday);
check("weekly Friday badge", JSON.stringify(weeklyJson.config.weekly_schedule.Friday) === JSON.stringify(["10:00"]), weeklyJson.config.weekly_schedule.Friday);
check("weekly has 7 day keys", Object.keys(weeklyJson.config.weekly_schedule).length === 7, Object.keys(weeklyJson.config.weekly_schedule));

console.log("== Save: pattern ==");
sandbox.addStage();                      // stage 1: interval default
sandbox.updateStageStrategy(1, "fixed"); // switch to fixed
byId("fixedTimeInput_1").value = "10:00";
