const patternJson = lastDownload.json;
check("pattern method", patternJson.method === "pattern", patternJson.method);
check("pattern has 2 stages", patternJson.config.stages.length === 2, patternJson.config.stages.length);
check("pattern stage1 strategy", patternJson.config.stages[0].strategy === "fixed", patternJson.config.stages[0]);
check("pattern stage1 times", JSON.stringify(patternJson.config.stages[0].config.times) === JSON.stringify(["10:00"]), patternJson.config.stages[0].config);
check("pattern stage2 interval cfg", patternJson.config.stages[1].config.interval_hour === 24, patternJson.config.stages[1].config);
check("pattern stage has duration/unit", patternJson.config.stages[0].duration !== undefined && patternJson.config.stages[0].unit === "days", patternJson.config.stages[0]);

