  revokeObjectURL() {},
};

// capture created <a> (download trigger)
const origCreateElement = documentStub.createElement;
documentStub.createElement = function (tag) {
  const el = makeEl();
  if (tag === "a") {
    el.click = function () { lastDownload.filename = el.download; lastDownload.href = el.href; };
  }
  return el;
};

let alerts = [];
let fetchCalls = [];
class FakeFileReader {
  readAsText(file) { this.result = file.__text; if (this.onload) this.onload({ target: this }); }
}

const sandbox = {
  document: documentStub,
  window: {},
  console: { log() {}, error() {}, warn() {} },
  bootstrap: { Tab: { getOrCreateInstance() { return { show() {} }; } } },
  Blob: FakeBlob,
  URL: URLStub,
  FormData: class { append() {} },
  alert(msg) { alerts.push(msg); },
  fetch() { fetchCalls.push(Array.prototype.slice.call(arguments)); return Promise.resolve({ json: () => Promise.resolve({}) }); },
  FileReader: FakeFileReader,
  setTimeout: setTimeout,
  JSON: JSON,
  Object: Object,
  Array: Array,
  Math: Math,
  Date: Date,
  parseInt: parseInt,
  parseFloat: parseFloat,
  isNaN: isNaN,
};
sandbox.globalThis = sandbox;

vm.createContext(sandbox);
vm.runInContext(appJs, sandbox, { filename: "app.js" });

